const theme = createTheme({
  palette: {
    background: {
      default: "#000000", // This sets the default background color for the body
    },
  },
  components: {
    MuiCssBaseline: {
      styleOverrides: {
        body: {
          backgroundColor: "black", // Set the background color
          backgroundImage: "url(/bg.jpg)", // Set the background image
          backgroundPosition: "center", // Center the background image
          backgroundRepeat: "no-repeat", // Prevent the image from repeating
          backgroundSize: "cover", // Make the image cover the entire viewport
